-- v0.8 🏰 Merge tiers: Estates.
-- Merge four plots of the same type into a 2x2 square and that land can become an Estate — a whole new, bigger place
-- built on the type you merged (or keep it as it is; switching between the two is free and both keep their progress):
--   🎨 Art Canvas      → 🖼️ Grand Atelier         (Hue Hunter: mix paint to match a colour)
--   🌳 Habitat         → 🦌 Wildwood Reserve      (Firefly Lantern: lead fireflies into jars, dodge owls)
--   🌾 Farm            → 🐎 Harvest Valley Ranch  (Sheepdog Roundup: herd the flock through the gate)
--   🍋 Business        → 🏙️ Skyline Exchange      (Market Maker: hold to buy, let go to sell)
--   🕹️ Arcade          → 🎡 Neon Boardwalk        (Pinball Wizard)
--   ⛏️ Crystal Mine    → 💎 Gemheart Caverns      (Crystal Echo: play the crystals' tune back)
--   ☁️ Sky Island      → 🎈 Aurora Skyport        (Airship Docking: ride the gusts down to the ring)
--   🛠️ Workshop        → ⚙️ Clockwork Foundry     (Rocket Stages: fire each stage in the green)
--   🍳 Restaurant      → 🍱 Grand Food Hall       (Sushi Train: serve each guest the dish they want)
--   ⚔️ Dungeon         → 🐉 Dragonspire Citadel   (Boss Rush: dodge the boss, grab swords, strike)
--   🎨 Paintbrawl      → 🏟️ Champions' Colosseum  (Card Clash: match pairs, chain combos)
-- Every Estate runs on the realm engine with its own currency, six resources, crew, upgrades, recipes, six zones,
-- twelve collection finds and a signature minigame, at about 1.5x the base places' rates (it costs four plots), and
-- starts with a charter of 250 of its currency (once per player and Estate type).
-- Rules: an Estate needs a full 2x2 square of plots in the group; merging keeps an Estate an Estate; detaching
-- (or anything else) that breaks the square turns it back into its base type.

insert into public.plot_kinds (id, name, description, sort) values
  ('atelier', 'Grand Atelier', 'Estate of the Art Canvas: Where the legends hang.', 20),
  ('reserve', 'Wildwood Reserve', 'Estate of the Inkborn Habitat: The ancient heart of the wood.', 21),
  ('ranch', 'Harvest Valley Ranch', 'Estate of the Farm: The county fair, every day.', 22),
  ('exchange', 'Skyline Exchange', 'Estate of the Business: The top of the world.', 23),
  ('boardwalk', 'Neon Boardwalk', 'Estate of the Arcade: The night sky explodes.', 24),
  ('gemheart', 'Gemheart Caverns', 'Estate of the Crystal Mine: The cavern’s beating heart.', 25),
  ('skyport', 'Aurora Skyport', 'Estate of the Sky Island: Ships leave here for the stars.', 26),
  ('foundry', 'Clockwork Foundry', 'Estate of the Inventor’s Workshop: The engine at the end of time.', 27),
  ('foodhall', 'Grand Food Hall', 'Estate of the Restaurant: Long tables for a feast.', 28),
  ('citadel', 'Dragonspire Citadel', 'Estate of the Dungeon: Where the citadel ends and something else begins.', 29),
  ('colosseum', 'Champions’ Colosseum', 'Estate of the Paintbrawl Arena: Only the best walk here.', 30)
on conflict (id) do nothing;

