 where key = 'realms';

-- ---- what's an Estate of what ------------------------------------------------------------------------------------
/** The base type an Estate kind is built on (null for anything that isn't an Estate). */
create or replace function private.estate_base(p_kind text) returns text language sql stable as $$
  select case when private.rlm_cfg(p_kind) ->> 'tier' = 'estate' then private.rlm_cfg(p_kind) ->> 'base' end
$$;
/** The Estate a base type upgrades to (null if it has none). */
create or replace function private.estate_of(p_base text) returns text language sql stable as $$
  select k from jsonb_each(private.cfg('realms') -> 'kinds') x(k, v) where v ->> 'tier' = 'estate' and v ->> 'base' = p_base order by k limit 1
$$;
/** A kind and its Estate are one family: they merge together. */
create or replace function private.kind_family(p_kind text) returns text language sql stable as $$
  select coalesce(private.estate_base(p_kind), p_kind)
$$;
create or replace function private.estate_kinds() returns text[] language sql stable as $$
  select coalesce(array_agg(k order by k), '{}') from jsonb_each(private.cfg('realms') -> 'kinds') x(k, v) where v ->> 'tier' = 'estate'
$$;
/** Does the group hold a full n x n square of plots? */
create or replace function private.group_has_square(p_group uuid, p_n int) returns boolean language sql stable as $$
  select exists (
    select 1 from public.canvas_group_members m
     where m.group_id = p_group
       and (select count(*) from generate_series(0, p_n - 1) i cross join generate_series(0, p_n - 1) j
              join public.canvas_group_members m2 on m2.gx = m.gx + i and m2.gy = m.gy + j and m2.group_id = p_group) = p_n * p_n)
$$;

/** Make sure the place behind a plot kind exists for this group (farm, business, arcade, realm, habitat). */
create or replace function private.ensure_kind_row(p_group uuid, p_owner uuid, p_kind text) returns void language plpgsql as $$
declare v_new boolean;
begin
  if p_kind = 'farm' then insert into public.farms (owner_id, group_id) values (p_owner, p_group) on conflict (group_id) do update set owner_id = excluded.owner_id; end if;
  if p_kind = 'business' then insert into public.businesses (owner_id, group_id) values (p_owner, p_group) on conflict (group_id) do update set owner_id = excluded.owner_id; end if;
  if p_kind = 'arcade' then insert into public.arcades (owner_id, group_id) values (p_owner, p_group) on conflict (group_id) do update set owner_id = excluded.owner_id; perform private.arc_player(p_owner); end if;
  if p_kind = 'habitat' and not exists (select 1 from public.habitats where group_id = p_group) then
    insert into public.habitats (owner_id, group_id, kind) values (p_owner, p_group, 'plot');
  end if;
  if p_kind in ('mine', 'sky', 'workshop', 'diner', 'dungeon', 'brawl') or private.estate_base(p_kind) is not null then
    -- an Estate's charter: a head start of its currency, the first time a player opens that kind of Estate
    v_new := private.estate_base(p_kind) is not null and not exists (select 1 from public.realm_players where player_id = p_owner and kind = p_kind);
    insert into public.realms (owner_id, group_id, kind) values (p_owner, p_group, p_kind) on conflict (group_id, kind) do update set owner_id = excluded.owner_id;
    perform private.rlm_player(p_owner, p_kind);
    if v_new then
      update public.realm_players set wallet = private.jadd(wallet, jsonb_build_object(private.rlm_cfg(p_kind) ->> 'currency', coalesce((private.rlm_cfg(p_kind) ->> 'charter')::int, 0)))
       where player_id = p_owner and kind = p_kind;
    end if;
  end if;
end $$;

/** After a merge: the land stays an Estate (as long as it holds the square). */
create or replace function private.estate_keep(p_group uuid, p_estate text) returns void language plpgsql as $$
declare g public.canvas_groups%rowtype;
begin
  select * into g from public.canvas_groups where id = p_group for update;
  if not found or g.kind = p_estate or private.kind_family(g.kind) <> private.estate_base(p_estate) then return; end if;
  if not private.group_has_square(g.id, 2) then return; end if;
  perform private.ensure_kind_row(g.id, g.owner_id, p_estate);
  update public.canvas_groups set kind = p_estate, updated_at = now() where id = g.id;
end $$;

/** An Estate that no longer holds a 2x2 square goes back to its base type. */
create or replace function private.estate_settle(p_group uuid) returns void language plpgsql as $$
declare g public.canvas_groups%rowtype; v_base text;
begin
  select * into g from public.canvas_groups where id = p_group;
  if not found then return; end if;
  v_base := private.estate_base(g.kind);
  if v_base is null or private.group_has_square(g.id, 2) then return; end if;
  perform private.ensure_kind_row(g.id, g.owner_id, v_base);
  update public.canvas_groups set kind = v_base, updated_at = now() where id = g.id;
  perform private.audit('group.kind', 'group', g.id::text, jsonb_build_object('from', g.kind, 'to', v_base, 'why', 'estate_square_broken'));
end $$;

-- checked when the transaction commits, so it sees a merge or detach in its final shape
create or replace function private.estate_settle_trg() returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if tg_op in ('DELETE', 'UPDATE') then perform private.estate_settle(old.group_id); end if;
  if tg_op in ('INSERT', 'UPDATE') then perform private.estate_settle(new.group_id); end if;
  return null;
end $$;
drop trigger if exists estate_settle on public.canvas_group_members;
create constraint trigger estate_settle after insert or update or delete on public.canvas_group_members
  deferrable initially deferred for each row execute function private.estate_settle_trg();

-- ---- choosing what the land is: keep the type, or upgrade to its Estate ------------------------------------------
create or replace function public.set_group_kind(p_group_id uuid, p_kind text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_uid uuid := private.require_active_player(); g public.canvas_groups%rowtype; h public.habitats%rowtype; v_starter uuid; v_fee int := 0; v_base text;
begin
  perform private.rate_limit('set_group_kind', 60, 3600);
  select * into g from public.canvas_groups where id = p_group_id for update;
  if not found or g.owner_id <> v_uid or g.status <> 'active' then raise exception 'not_owner' using errcode = 'P0001'; end if;
  if not exists (select 1 from public.plot_kinds where id = p_kind and enabled) then raise exception 'invalid_plot_kind' using errcode = 'P0001'; end if;
  if g.kind = p_kind then return private.group_json(g.id); end if;
  -- an Estate is an upgrade of its base type, for land holding a full 2x2 square
  v_base := private.estate_base(p_kind);
  if v_base is not null then
    if private.kind_family(g.kind) <> v_base then raise exception 'estate_wrong_type' using errcode = 'P0001', detail = v_base; end if;
    if not private.group_has_square(g.id, 2) then raise exception 'estate_needs_square' using errcode = 'P0001'; end if;
  end if;
  -- choosing what a brand-new plot becomes is free, and so is moving between a type and its Estate; otherwise a little Ink
  if private.kind_family(g.kind) <> private.kind_family(p_kind)
     and (g.kind_changed_at is not null or g.created_at < now() - make_interval(mins => coalesce((private.cfg('plot_switch') ->> 'free_minutes')::int, 15))) then
    v_fee := coalesce((private.cfg('plot_switch') ->> 'fee')::int, 20);
    if v_fee > 0 then perform private.charge(v_uid, jsonb_build_object('ink', v_fee), 'plot_switch', 'group', g.id::text, 'plot-switch:' || g.id || ':' || gen_random_uuid()); end if;
  end if;
  if exists (select 1 from public.artwork_publications where group_id = g.id and status in ('processing', 'pending_review', 'approved', 'uploading')) then
    raise exception 'publication_in_progress' using errcode = 'P0001';
  end if;
  select * into h from public.habitats where group_id = g.id;
  if p_kind = 'business' then perform private.ensure_kind_row(g.id, v_uid, p_kind); perform private.biz_lock(v_uid);
  elsif p_kind <> 'habitat' then perform private.ensure_kind_row(g.id, v_uid, p_kind);
  end if;
  if p_kind = 'habitat' then
    if h.id is null then insert into public.habitats (owner_id, group_id, kind) values (v_uid, g.id, 'plot') returning * into h; end if;
    -- creatures that lived here before come home
    update public.inkborn set habitat_id = h.id, prev_habitat_id = null where owner_id = v_uid and prev_habitat_id = h.id;
  elsif h.id is not null then
    -- the habitat (layout + who lived here) is kept; its creatures wait in the starter sanctuary
    v_starter := private.starter_habitat(v_uid);
    update public.inkborn set prev_habitat_id = h.id, habitat_id = v_starter where habitat_id = h.id;
  end if;
  update public.canvas_groups set kind = p_kind, kind_changed_at = now(), updated_at = now() where id = g.id;
  perform private.audit('group.kind', 'group', g.id::text, jsonb_build_object('from', g.kind, 'to', p_kind));
  return private.group_json(g.id) || jsonb_build_object('fee', v_fee, 'balances', private.balances(v_uid));
end $$;

-- ---- merging: an Estate merges with its base type ------------------------------------------------------------------
create or replace function public.fuse_groups(p_group_ids jsonb, p_name text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_estate text;
  v_uid uuid := private.require_active_player(); v_ids uuid[]; v_cost int; v_effort bigint; v_res jsonb; v_version uuid; v_have bigint;
begin
  select array_agg(distinct x::uuid) into v_ids from jsonb_array_elements_text(p_group_ids) x;
  -- art canvases merge with art canvases, habitats with habitats
  if (select count(distinct private.kind_family(kind)) from public.canvas_groups where id = any(coalesce(v_ids, '{}'))) > 1 then
    raise exception 'mixed_plot_kinds' using errcode = 'P0001';
  end if;
  v_cost := private.fuse_added_plots((select array_agg(id) from public.canvas_groups where id = any(coalesce(v_ids, '{}')) and owner_id = v_uid))
            * coalesce((private.cfg('earn') -> 'merge' ->> 'ink_per_plot')::int, 0);
  if v_cost > 0 then
    select coalesce(amount, 0) into v_have from public.resource_balances where player_id = v_uid and resource = 'ink';
    if coalesce(v_have, 0) < v_cost then raise exception 'insufficient_funds' using errcode = 'P0001', detail = v_cost::text; end if;
  end if;
  -- painting time carries over: the merged canvas keeps the time spent on every part
  select coalesce(sum(private.version_effort_of(pr.current_version_id)), 0) into v_effort
    from public.canvas_groups g join public.artwork_projects pr on pr.id = g.project_id
   where g.id = any(coalesce(v_ids, '{}')) and g.owner_id = v_uid;
  -- an Estate among the merging groups stays an Estate (the merged land still holds its 2x2 square)
  select max(kind) filter (where private.estate_base(kind) is not null) into v_estate
    from public.canvas_groups where id = any(coalesce(v_ids, '{}')) and owner_id = v_uid;
  v_res := private.fuse_groups_core(p_group_ids, p_name);
  if v_estate is not null then perform private.estate_keep((v_res ->> 'id')::uuid, v_estate); v_res := v_res || jsonb_build_object('kind', v_estate); end if;
  select pr.current_version_id into v_version from public.canvas_groups g join public.artwork_projects pr on pr.id = g.project_id
   where g.id = (v_res ->> 'id')::uuid;
  if v_version is not null then
    update private.version_effort set effort_ms = greatest(effort_ms, v_effort) where version_id = v_version;
  end if;
  -- connected habitats become one sanctuary: creatures from the merged habitats move in
  perform private.habitat_after_fuse((v_res ->> 'id')::uuid);
  if v_cost > 0 then
    perform private.charge(v_uid, jsonb_build_object('ink', v_cost), 'merge', 'group', v_res ->> 'id', 'merge:' || (v_res ->> 'id') || ':' || v_version);
  end if;
  return v_res || jsonb_build_object('ink_spent', v_cost, 'balances', private.balances(v_uid));
end $$;


-- ---- no art on Estates (like every place that isn't an art canvas) -------------------------------------------------
create or replace function private.no_art_on_habitat_trg() returns trigger language plpgsql as $$
begin
  if exists (select 1 from public.canvas_groups where id = new.group_id
              and (kind in ('habitat', 'farm', 'business', 'arcade', 'mine', 'sky', 'workshop', 'diner', 'dungeon', 'brawl') or private.estate_base(kind) is not null)) then
    raise exception 'habitat_plot' using errcode = 'P0001';
  end if;
  return new;
end $$;

do $$
declare f text;
begin
  foreach f in array array['private.estate_base(text)', 'private.estate_of(text)', 'private.kind_family(text)', 'private.estate_kinds()',
    'private.group_has_square(uuid, int)', 'private.ensure_kind_row(uuid, uuid, text)', 'private.estate_keep(uuid, text)',
    'private.estate_settle(uuid)', 'private.estate_settle_trg()'] loop
    execute 'revoke all on function ' || f || ' from public, anon, authenticated';
  end loop;
end $$;
